  "rows": [
    [
      {
        "text": "UNITED KINGDOM",
        "font_size": 22,
        "color": "#1C1A17"
      },
      {
        "font_size": 16,
        "color": "#1C1A17",
        "paragraphs": [
          {
            "text": "Alison and Peter Smithson (pioneers) · Ernő Goldfinger · Chamberlin, Powell and Bon (Barbican) ·"
          },
          {
            "text": "Denys Lasdun (National Theatre) · Norman Engleback (Hayward Gallery) · Basil Spence · Owen Luder"
          },
          {
            "text": "· John Bancroft · Leslie Martin · James Stirling with James Gowan · LCC/GLC Architects Dept"
          }
        ]
      }
    ],
    [
      {
        "text": "UNITED STATES",
        "font_size": 22,
        "color": "#1C1A17"
      },
      {
        "font_size": 16,
        "color": "#1C1A17",
        "paragraphs": [
          {
            "text": "Evans Woollen III (brought the style to Indianapolis) · Walter Netsch (academic buildings) ·"
          },
          {
            "text": "Marcel Breuer (curves, not corners) · Eero Saarinen (Milwaukee County War Memorial, 1957) · Ted"
          },
          {
            "text": "Levy (Plaza Towers, Atlanta) · Louis Kahn, opposed to its posturing yet informed by it"
          }
        ]
      }
    ],
    [
      {
        "text": "AUSTRALIA",
        "font_size": 22,
        "color": "#1C1A17"
      },
      {
        "font_size": 16,
        "color": "#1C1A17",
        "paragraphs": [
          {
            "text": "Robin Gibson (Queensland Art Gallery) · Ken Woolley (Fisher Library, Sydney) · Christopher"
          },
          {
            "text": "Kringas (High Court of Australia) · John Andrews · Daryl Jackson and Kevin Borland (Harold Holt"
          },
          {
            "text": "Memorial Swimming Centre, Malvern, 1967)"
          }
        ]
      }
    ],
    [
      {
        "text": "CANADA",
        "font_size": 22,
        "color": "#1C1A17"
      },
      {
        "font_size": 16,
        "color": "#1C1A17",
        "paragraphs": [
          {
            "text": "Arthur Erickson (Simon Fraser University, MacMillan Bloedel Building, UBC Museum of"
          },
          {
            "text": "Anthropology, Vancouver Law Courts) · Green Blankstein Russell (Winnipeg Civic Centre) · Waisman"
          },
          {
            "text": "Ross Blankstein Coop Gillmor Hanna (Manitoba Students' Union; Royal Manitoba Theatre Centre)"
          }
        ]
